/* =================================================================
   HLD Design System — Color Tokens
   Hyper Light Drifter + Ableton Live Session View
   "A DAW that feels like exploring a neon-lit dungeon"
   ================================================================= */

/* Self-hosted technical fonts. UI and body copy use the native platform
   sans-serif for maximum legibility; JetBrains Mono remains available for
   notes, channels, measurements, and other aligned technical readouts. */
@font-face {
	font-family: 'Space Grotesk';
	font-style: normal;
	font-weight: 400;
	font-display: swap;
	src: url('/fonts/space-grotesk-400.woff2') format('woff2');
}
@font-face {
	font-family: 'Space Grotesk';
	font-style: normal;
	font-weight: 500;
	font-display: swap;
	src: url('/fonts/space-grotesk-500.woff2') format('woff2');
}
@font-face {
	font-family: 'Space Grotesk';
	font-style: normal;
	font-weight: 600;
	font-display: swap;
	src: url('/fonts/space-grotesk-600.woff2') format('woff2');
}
@font-face {
	font-family: 'Space Grotesk';
	font-style: normal;
	font-weight: 700;
	font-display: swap;
	src: url('/fonts/space-grotesk-700.woff2') format('woff2');
}
@font-face {
	font-family: 'JetBrains Mono';
	font-style: normal;
	font-weight: 400;
	font-display: swap;
	src: url('/fonts/jetbrains-mono-400.woff2') format('woff2');
}
@font-face {
	font-family: 'JetBrains Mono';
	font-style: normal;
	font-weight: 500;
	font-display: swap;
	src: url('/fonts/jetbrains-mono-500.woff2') format('woff2');
}
@font-face {
	font-family: 'JetBrains Mono';
	font-style: normal;
	font-weight: 600;
	font-display: swap;
	src: url('/fonts/jetbrains-mono-600.woff2') format('woff2');
}
@font-face {
	font-family: 'JetBrains Mono';
	font-style: normal;
	font-weight: 700;
	font-display: swap;
	src: url('/fonts/jetbrains-mono-700.woff2') format('woff2');
}
@font-face {
	font-family: 'JetBrains Mono';
	font-style: normal;
	font-weight: 800;
	font-display: swap;
	src: url('/fonts/jetbrains-mono-800.woff2') format('woff2');
}

:root {
	/* === Background Layers (deep to shallow) === */
	--color-bg-deep: #0a0a1a;           /* Deepest void — full-screen background */
	--color-bg-base: #0f0e1a;           /* Primary background — deep indigo/navy */
	--color-bg-panel: #151428;          /* Panel backgrounds — raised surfaces */
	--color-widget-bg: #1a1833;         /* Widget containers */
	--color-widget-inactive: #25223d;   /* Inactive widget state */

	/* === HLD Accent Colors (Neon-on-Dark) === */
	--color-accent-magenta: #ff3388;       /* Primary accent — HLD signature pink/magenta */
	--color-accent-magenta-dim: #cc2266;   /* Dimmed magenta for subtle uses */
	--color-accent-cyan: #33ddff;          /* Secondary accent — electric cyan */
	--color-accent-cyan-dim: #2299cc;      /* Dimmed cyan */
	--color-accent-teal: #00ccaa;          /* Tertiary — deep teal */
	--color-accent-pink: #ff77aa;          /* Soft pink for highlights */
	--color-accent-amber: #ffaa33;         /* Warm accent (interchange/borrowed) */
	--color-accent-gold: #ffdd44;          /* Bright gold for emphasis */

	/* === Sacred Piano Key Colors (PRESERVED from egui) === */
	--color-piano-input: #00e436;       /* Green — input notes (melody) */
	--color-piano-harmony: #ff9933;     /* Orange — harmony notes (generated) */
	--color-piano-borrowed: #ffaa33;    /* Amber — interchange borrowed notes */
	--color-piano-in-scale: #1a1844;    /* Subtle tint for in-scale keys */

	/* === Text === */
	--color-text-primary: #e8e0f0;      /* Light lavender — easier on eyes than pure white */
	--color-text-secondary: #8888aa;    /* Muted purple-gray */
	--color-text-dim: #555577;          /* Very muted — labels, placeholders */

	/* === Borders === */
	--color-border: #2a2848;            /* Subtle purple border */
	--color-border-active: #ff3388;     /* Magenta glow on active elements */

	/* === Glow Effects (toggled by .reduced-motion) === */
	--glow-magenta: 0 0 8px #ff338855, 0 0 20px #ff338822;
	--glow-cyan: 0 0 8px #33ddff55, 0 0 20px #33ddff22;
	--glow-teal: 0 0 8px #00ccaa55, 0 0 20px #00ccaa22;

	/* === Typography ===
	   Native UI typography is clearer at compact DAW sizes and needs no
	   runtime font download. JetBrains Mono is reserved for data. */
	--font-grotesk: 'Space Grotesk', ui-sans-serif, system-ui, sans-serif;
	--font-jetbrains: 'JetBrains Mono', ui-monospace, monospace;
	--font-reading: system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;

	/* Semantic font roles. */
	--font-display: var(--font-reading);
	--font-ui: var(--font-reading);
	--font-code: var(--font-jetbrains);
	--font-mono: var(--font-jetbrains);
	--font-body: var(--font-reading);

	/* Base font sizes scale with viewport so the UI stays proportional
	   on any monitor. clamp(min, responsive, max) keeps them legible
	   everywhere without going microscopic or huge. Multiplied by
	   --font-scale for the user-controlled font-size slider (range
	   0.75–1.5) — independent of --ui-scale which zooms layout. */
	--font-size-xs: calc(clamp(11px, 0.75vmin + 7px, 14px) * var(--font-scale));
	--font-size-sm: calc(clamp(13px, 0.9vmin + 7px, 17px) * var(--font-scale));
	--font-size-md: calc(clamp(12px, 1.1vmin + 8px, 20px) * var(--font-scale));
	--font-size-lg: calc(clamp(16px, 1.5vmin + 10px, 28px) * var(--font-scale));
	--font-size-xl: calc(clamp(24px, 2.2vmin + 14px, 40px) * var(--font-scale));

	/* User-controlled scales.
	   --ui-scale  → zooms entire layout via html { zoom }. Range 0.75–2.0.
	   --font-scale → multiplies font sizes only. Range 0.75–1.5. */
	--ui-scale: 1;
	--font-scale: 1;
}

/* === Performance Toggle ===
   Add .reduced-motion to <html> or <body> to disable all glow and animations.
   Intended for lower-powered machines or user preference.
*/
.reduced-motion,
.reduced-motion * {
	--glow-magenta: none;
	--glow-cyan: none;
	--glow-teal: none;
	animation: none !important;
	transition: none !important;
}

