text:
@import "tailwindcss";
@import "$lib/theme/tokens.css";
@import "$lib/theme/pixel.css";

/* Global UI scale. User-configurable via ui store; defaults to 1.0.
   `zoom` scales everything (layout, text, borders) proportionally;
   it's supported in all modern browsers and Tauri's WebView. */
html {
	zoom: var(--ui-scale);
}

body {
	background: var(--color-bg-deep);
	color: var(--color-text-primary);
	font-family: var(--font-body);
	margin: 0;
	overflow: hidden;
	-webkit-font-smoothing: antialiased;
	-moz-osx-font-smoothing: grayscale;
	text-rendering: optimizeLegibility;
}

/* Semantic role utilities. The native UI font carries labels and prose;
   JetBrains Mono is reserved for aligned musical/technical data. Keep the
   retro geometry and color, but never sacrifice glyph legibility. */
.font-ui,
.pixel-btn {
	font-family: var(--font-ui);
	font-weight: 500;
}
.font-code {
	font-family: var(--font-code);
}

.font-ui,
.font-code,
.pixel-btn,
button,
input,
select {
	-webkit-font-smoothing: antialiased !important;
	-moz-osx-font-smoothing: grayscale !important;
	text-rendering: optimizeLegibility !important;
}
.font-body {
	font-family: var(--font-body);
}
.font-display {
	font-family: var(--font-display);
}

