  1	<script lang="ts">
  2		import { onMount } from 'svelte';
  3		import { guitar } from '$lib/stores/guitar.svelte';
  4		import { engine } from '$lib/stores/engine.svelte';
  5		import { midi } from '$lib/stores/midi.svelte';
  6		import PixelSelect from './PixelSelect.svelte';
  7		import SignalGraphs from './SignalGraphs.svelte';
  8	
  9		const GUITAR_AUDIO_SENTINEL = 999_997;
 10	
 11		const techniques = [
 12			{ key: 'bends' as const, label: 'BENDS', get active() { return guitar.bendsEnabled; } },
 13			{ key: 'legato' as const, label: 'LEGATO', get active() { return guitar.legatoEnabled; } },
 14			{ key: 'slides' as const, label: 'SLIDES', get active() { return guitar.slidesEnabled; } },
 15			{ key: 'vibrato' as const, label: 'VIBRATO', get active() { return guitar.vibratoEnabled; } },
 16		];
 17	
 18		let latencyDisplay = $derived(`${guitar.latencyMs}ms`);
 19		let gainDisplay = $derived(guitar.gain.toFixed(2));
 20		let confidenceDisplay = $derived(`${Math.round(guitar.stringConfidence * 100)}%`);
 21	
 22		let detectionLine = $derived(
 23			guitar.detecting
 24				? guitar.currentNote
 25					? `${guitar.currentNote}  ·  ${guitar.confidence}%  ·  Input ${guitar.activeChannel}`
 26					: `Listening  ·  Input ${guitar.activeChannel}`
 27				: `Ready  ·  Input ${guitar.selectedChannel}`
 28		);
 29	
 30		let channelMismatch = $derived(
 31			guitar.detecting &&
 32			guitar.activeChannel > 0 &&
 33			guitar.activeChannel !== guitar.selectedChannel
 34		);
 35	
 36		let deviceOptions = $derived(
 37			guitar.audioDevices.map((d) => ({
 38				value: d.deviceId,
 39				label: d.label || `Audio Device ${d.deviceId.slice(0, 8)}`
 40			}))
 41		);
 42	
 43		let channelNumbers = $derived(
 44			Array.from({ length: guitar.maxChannels }, (_, i) => i + 1)
 45		);
 46	
 47		async function applyInputChange(change: () => void) {
 48			const restart = engine.isRunning && midi.selectedInput === GUITAR_AUDIO_SENTINEL;
 49			guitar.audioDeviceError = '';
 50			try {
 51				if (restart) await engine.stop();
 52				change();
 53				await guitar.syncDevice();
 54				if (restart) await engine.start(GUITAR_AUDIO_SENTINEL, midi.selectedOutputs);
 55			} catch (error) {
 56				guitar.audioDeviceError = `Could not switch guitar input: ${error}`;
 57			}
 58		}
 59	
 60		async function handleDeviceChange(value: string) {
 61			if (value) await applyInputChange(() => guitar.selectDevice(value));
 62		}
 63	
 64		async function handleChannelChange(ch: number) {
 65			await applyInputChange(() => guitar.selectChannel(ch));
 66		}
 67	
 68		function handleTechniqueToggle(technique: 'bends' | 'legato' | 'slides' | 'vibrato') {
 69			guitar.toggleTechnique(technique);
 70			guitar.syncConfig();
 71		}
 72	
 73		/** Build a text-based cents meter for the tuner. */
 74		function buildMeter(cents: number): string {
 75			const width = 21;
 76			const center = Math.floor(width / 2);
 77			const pos = Math.round((cents / 50) * center + center);
 78			const clamped = Math.max(0, Math.min(width - 1, pos));
 79			const bar = '-'.repeat(width).split('');
 80			bar[center] = '|';
 81			if (Math.abs(cents) <= 5) {
 82				bar[clamped] = '*';
 83			} else {
 84				bar[clamped] = '#';
 85			}
 86			return '[' + bar.join('') + ']';
 87		}
 88	
 89		/** Build a hold progress bar. */
 90		function buildHoldBar(progress: number): string {
 91			const width = 10;
 92			const filled = Math.round(progress * width);
 93			return '\u2588'.repeat(filled) + '\u2591'.repeat(width - filled);
 94		}
 95	
 96		const OPEN_CONFIDENCES = [
 97			{ name: 'Low E', note: 'E2', midi: 40, freq: 82.41 },
 98			{ name: 'A', note: 'A2', midi: 45, freq: 110.00 },
 99			{ name: 'D', note: 'D3', midi: 50, freq: 146.83 },
100			{ name: 'G', note: 'G3', midi: 55, freq: 196.00 },
101			{ name: 'B', note: 'B3', midi: 59, freq: 246.94 },
102			{ name: 'High E', note: 'E4', midi: 64, freq: 329.63 },
103		];
104	
105		let tunerTarget = $derived(OPEN_CONFIDENCES[guitar.tunerStringIndex]);
106	
107		onMount(() => {
108			guitar.enumerateAudioDevices();
109			guitar.loadAudioDevices();
110			void guitar.syncConfig();
111		});
112	</script>
113	
114	{#if guitar.tunerActive}
115		<!-- ============ TUNER UI ============ -->
116		<div class="guitar-panel pixel-card tuner-panel">
117			<div class="panel-header font-ui">GUITAR INPUT</div>
118	
119			{#if guitar.tunerPhase === 'noise-floor'}
120				<div class="tuner-section">
121					<div class="tuner-title font-ui">TUNE GUITAR</div>
122					<div class="tuner-separator"></div>
123					<div class="tuner-instruction font-ui">Measuring noise floor...</div>
124					<div class="tuner-instruction font-ui">Keep quiet for 3 seconds</div>
125					<div class="noise-progress-bar">
126						<div class="noise-progress-fill" style:width="{guitar.tunerNoiseProgress * 100}%"></div>
127					</div>
128					<div class="tuner-actions">
129						<button class="tuner-btn pixel-btn" onclick={() => guitar.cancelTuner()}>CANCEL</button>
130					</div>
131				</div>
132	
133			{:else if guitar.tunerPhase === 'tuning'}
134				<div class="tuner-section">
135					<div class="tuner-title font-ui">TUNING -- String {guitar.tunerStringIndex + 1} of 6</div>
136					<div class="tuner-separator"></div>
137	
138					<div class="tuner-target font-code">
139						Pluck {tunerTarget.name} ({tunerTarget.note})
140					</div>
141	
142					{#if guitar.tunerStatus === 'waiting'}
143						<div class="tuner-detected font-ui tuner-dim">Waiting for signal...</div>
144						<div class="tuner-meter font-code tuner-dim">{buildMeter(0)}</div>
145					{:else}
146						<div class="tuner-detected font-code">
147							<span class="tuner-note">{guitar.tunerDetectedNote}</span>
148							<span class="tuner-cents" class:tuner-cents-good={Math.abs(guitar.tunerCents) <= 8} class:tuner-cents-bad={Math.abs(guitar.tunerCents) > 8}>
149								{guitar.tunerCents >= 0 ? '+' : ''}{guitar.tunerCents} cents
150							</span>
151						</div>
152						<div class="tuner-meter font-code" class:meter-intune={Math.abs(guitar.tunerCents) <= 8} class:meter-off={Math.abs(guitar.tunerCents) > 8}>
153							{buildMeter(guitar.tunerCents)}
154						</div>
155	
156						{#if guitar.tunerStatus === 'sharp'}
157							<div class="tuner-advice font-ui tuner-amber">SHARP -- tune down</div>
158						{:else if guitar.tunerStatus === 'flat'}
159							<div class="tuner-advice font-ui tuner-amber">FLAT -- tune up</div>
160						{:else if guitar.tunerStatus === 'holding' || guitar.tunerStatus === 'in-tune'}
161							<div class="tuner-advice font-ui tuner-cyan">IN TUNE</div>
162							<div class="tuner-hold font-code tuner-cyan">
163								{buildHoldBar(guitar.tunerHoldProgress)} holding...
164							</div>
165						{/if}
166					{/if}
167	
168					<div class="tuner-actions">
169						<button class="tuner-btn pixel-btn" onclick={() => guitar.skipTunerString()}>SKIP</button>
170						<button class="tuner-btn pixel-btn" onclick={() => guitar.cancelTuner()}>CANCEL</button>
171					</div>
172				</div>
173	
174			{:else if guitar.tunerPhase === 'complete'}
175				<div class="tuner-section">
176					<div class="tuner-title font-ui tuner-cyan">TUNING COMPLETE</div>
177					<div class="tuner-separator"></div>
178					<div class="tuner-instruction font-ui tuner-cyan">All 6 strings tuned!</div>
179					<div class="tuner-actions">
180						<button class="tuner-btn pixel-btn" onclick={() => { guitar.tunerActive = false; }}>CLOSE</button>
181					</div>
182				</div>
183			{/if}
184		</div>
185	
186	{:else}
187		<!-- ============ NORMAL PANEL ============ -->
188		<div class="guitar-panel pixel-card">
189			<div class="panel-header font-ui">GUITAR INPUT</div>
190	
191			<!-- Audio device + channel selector -->
192			<div class="device-section">
193				<span class="device-label font-ui">DEVICE</span>
194				{#if guitar.audioDeviceError}
195					<div class="device-error font-ui">{guitar.audioDeviceError}</div>
196				{:else}
197					<div class="device-select-row">
198						<PixelSelect
199							options={deviceOptions}
200							value={guitar.selectedDeviceId}
201							placeholder="Select device..."
202							small={true}
203							onchange={handleDeviceChange}
204						/>
205					</div>
206					<div class="channel-header">
207						<span class="device-label font-ui channel-label">INPUT CHANNEL</span>
208						<label class="channel-override font-ui" title="Detected number of interface inputs; override only if detection is wrong">
209							INPUTS
210							<input
211								type="number"
212								class="channel-count-input font-code"
213								min="1"
214								max="32"
215								value={guitar.maxChannels}
216								aria-label="Available input channels"
217								onchange={(e) => {
218									const val = parseInt((e.target as HTMLInputElement).value, 10);
219									if (val >= 1 && val <= 32) guitar.setManualMaxChannels(val);
220								}}
221								title="Override detected channel count for your audio interface"
222							/>
223						</label>
224					</div>
225					<div class="channel-row">
226						{#each channelNumbers as ch}
227							<button
228								class="channel-btn font-code"
229								class:channel-active={guitar.selectedChannel === ch}
230								onclick={() => handleChannelChange(ch)}
231							>
232								{ch}
233							</button>
234						{/each}
235					</div>
236				{/if}
237			</div>
238	
239			<!-- Interactive Dials row -->
240			<div class="dials-row">
241				<div class="dial-container">
242					<div class="dial dial-cyan">
243						<button class="dial-arrow dial-up font-ui" onclick={() => guitar.setLatency(guitar.latencyMs + 1)} aria-label="Increase latency">+</button>
244						<span class="dial-value">{latencyDisplay}</span>
245						<button class="dial-arrow dial-down font-ui" onclick={() => guitar.setLatency(guitar.latencyMs - 1)} aria-label="Decrease latency">-</button>
246					</div>
247					<span class="dial-label font-ui">LATENCY</span>
248				</div>
249	
250				<div class="dial-container">
251					<div class="dial dial-amber">
252						<button class="dial-arrow dial-up font-ui" onclick={() => guitar.setGain(guitar.gain + 0.05)} aria-label="Increase gain">+</button>
253						<span class="dial-value">{gainDisplay}</span>
254						<button class="dial-arrow dial-down font-ui" onclick={() => guitar.setGain(guitar.gain - 0.05)} aria-label="Decrease gain">-</button>
255					</div>
256					<span class="dial-label font-ui">GAIN</span>
257				</div>
258	
259				<div class="dial-container">
260					<div class="dial dial-teal">
261						<button class="dial-arrow dial-up font-ui" onclick={() => guitar.setStringConfidence(guitar.stringConfidence + 0.05)} aria-label="Increase confidence">+</button>
262						<span class="dial-value">{confidenceDisplay}</span>
263						<button class="dial-arrow dial-down font-ui" onclick={() => guitar.setStringConfidence(guitar.stringConfidence - 0.05)} aria-label="Decrease confidence">-</button>
264					</div>
265					<span class="dial-label font-ui">CONFIDENCE</span>
266				</div>
267			</div>
268	
269			<!-- Technique toggles -->
270			<div class="techniques-row">
271				{#each techniques as tech}
272					<button
273						class="technique-btn pixel-btn"
274						class:technique-active={tech.active}
275						aria-pressed={tech.active}
276						onclick={() => handleTechniqueToggle(tech.key)}
277					>
278						{tech.label}
279					</button>
280				{/each}
281			</div>
282	
283			<!-- Truthful tuner workflow: this tunes strings; detector profiles are separate. -->
284			<button
285				class="calibrate-btn pixel-btn"
286				class:calibrating={guitar.calibrating}
287				disabled={guitar.calibrating}
288				onclick={() => guitar.startCalibration()}
289			>
290				{guitar.calibrating ? 'TUNING...' : 'TUNE GUITAR'}
291			</button>
292	
293			<!-- Open the guitar pipeline debug window (Tauri only — no-op in browser) -->
294			<button
295				class="calibrate-btn pixel-btn"
296				onclick={async () => {
297					try {
298						const { invoke } = await import('@tauri-apps/api/core');
299						await invoke('open_debug_pipeline_window');
300					} catch (e) {
301						console.warn('[guitar] debug window unavailable (browser?):', e);
302					}
303				}}
304			>
305				DEBUG PIPELINE
306			</button>
307			{#if guitar.calibrationStatus}
308				<div class="calibration-status font-ui" class:calibrated={guitar.calibrated}>
309					{guitar.calibrationStatus}
310				</div>
311			{/if}
312	
313			<!-- Live detection status -->
314			<div class="detection-status font-ui" class:detecting={guitar.detecting}>
315				{detectionLine}
316			</div>
317			{#if channelMismatch}
318				<div class="channel-warning font-ui">
319					Input {guitar.activeChannel} is active; Input {guitar.selectedChannel} is selected.
320				</div>
321			{/if}
322	
323			<!-- Signal graphs (MiGiC-style) -->
324			<SignalGraphs />
325		</div>
326	{/if}
327	
328	<style>
329		.guitar-panel {
330			padding: 6px;
331			margin-bottom: 4px;
332		}
333	
334		.panel-header {
