  1	<script lang="ts">
  2		import { guitar } from '$lib/stores/guitar.svelte';
  3	
  4		let ampCanvas: HTMLCanvasElement;
  5		let animFrame: number | null = null;
  6	
  7		const WIDTH = 240;
  8		const HEIGHT = 48;
  9	
 10		function drawGraph(
 11			canvas: HTMLCanvasElement,
 12			data: number[],
 13			threshold: number | null,
 14			color: string,
 15			thresholdColor: string
 16		) {
 17			const ctx = canvas.getContext('2d');
 18			if (!ctx) return;
 19	
 20			ctx.clearRect(0, 0, WIDTH, HEIGHT);
 21	
 22			// Draw filled signal area
 23			if (data.length > 1) {
 24				ctx.beginPath();
 25				ctx.moveTo(0, HEIGHT);
 26				for (let i = 0; i < data.length; i++) {
 27					const x = (i / (data.length - 1)) * WIDTH;
 28					const y = HEIGHT - data[i] * HEIGHT;
 29					ctx.lineTo(x, y);
 30				}
 31				ctx.lineTo(WIDTH, HEIGHT);
 32				ctx.closePath();
 33				ctx.fillStyle = color + '40'; // semi-transparent fill
 34				ctx.fill();
 35	
 36				// Draw signal line on top
 37				ctx.beginPath();
 38				for (let i = 0; i < data.length; i++) {
 39					const x = (i / (data.length - 1)) * WIDTH;
 40					const y = HEIGHT - data[i] * HEIGHT;
 41					if (i === 0) ctx.moveTo(x, y);
 42					else ctx.lineTo(x, y);
 43				}
 44				ctx.strokeStyle = color;
 45				ctx.lineWidth = 1.5;
 46				ctx.stroke();
 47			}
 48	
 49			// Draw threshold line
 50			if (threshold !== null && threshold > 0) {
 51				const ty = HEIGHT - threshold * HEIGHT;
 52				ctx.beginPath();
 53				ctx.moveTo(0, ty);
 54				ctx.lineTo(WIDTH, ty);
 55				ctx.strokeStyle = thresholdColor;
 56				ctx.lineWidth = 1;
 57				ctx.setLineDash([4, 3]);
 58				ctx.stroke();
 59				ctx.setLineDash([]);
 60			}
 61		}
 62	
 63		function render() {
 64			if (ampCanvas) {
 65				const noiseThreshold = guitar.noiseGateEnabled
 66					? guitar.noiseGateThreshold * 5 // scale to match signalLevel (rms * 5)
 67					: null;
 68				drawGraph(ampCanvas, guitar.amplitudeHistory, noiseThreshold, '#00e5cc', '#ffaa00');
 69			}
 70			animFrame = requestAnimationFrame(render);
 71		}
 72	
 73		$effect(() => {
 74			if (guitar.detecting && ampCanvas) {
 75				if (!animFrame) render();
 76			}
 77			return () => {
 78				if (animFrame) {
 79					cancelAnimationFrame(animFrame);
 80					animFrame = null;
 81				}
 82			};
 83		});
 84	</script>
 85	
 86	<div class="graphs-container">
 87		<div class="graph-row">
 88			<span class="graph-label font-ui">AMP</span>
 89			<canvas bind:this={ampCanvas} width={WIDTH} height={HEIGHT} class="signal-canvas"></canvas>
 90			<div class="gate-controls">
 91				<button
 92					class="gate-btn font-ui"
 93					class:gate-on={guitar.noiseGateEnabled}
 94					onclick={() => { guitar.noiseGateEnabled = !guitar.noiseGateEnabled; }}
 95					title="Noise Gate"
 96				>NG</button>
 97				<input
 98					type="range"
 99					class="gate-slider"
100					min="0.001"
101					max="0.1"
102					step="0.001"
103					value={guitar.noiseGateThreshold}
104					oninput={(e) => { guitar.noiseGateThreshold = parseFloat((e.target as HTMLInputElement).value); }}
105					title={`Threshold: ${(guitar.noiseGateThreshold * 1000).toFixed(0)} mRMS`}
106				/>
107			</div>
108		</div>
109	</div>
