111	<style>
112		.graphs-container {
113			display: flex;
114			flex-direction: column;
115			gap: 3px;
116			margin: 4px 0;
117		}
118	
119		.graph-row {
120			display: flex;
121			align-items: center;
122			gap: 4px;
123		}
124	
125		.graph-label {
126			font-size: var(--font-size-xs);
127			color: var(--color-text-dim);
128			width: 18px;
129			text-align: right;
130		}
131	
132		.signal-canvas {
133			flex: 1;
134			height: 48px;
135			background: var(--color-bg-dark, #0a0a0a);
136			border: 1px solid var(--color-border);
137			image-rendering: pixelated;
138		}
139	
140		.gate-controls {
141			display: flex;
142			flex-direction: column;
143			align-items: center;
144			gap: 2px;
145			width: 32px;
146		}
147	
148		.gate-btn {
149			font-size: var(--font-size-xs);
150			padding: 2px 4px;
151			background: var(--color-widget-inactive);
152			border: 1px solid var(--color-border);
153			color: var(--color-text-dim);
154			cursor: pointer;
155		}
156	
157		.gate-btn.gate-on {
158			background: var(--color-accent-teal);
159			color: #fff;
160			border-color: var(--color-accent-cyan-dim);
161		}
162	
163		.gate-slider {
164			width: 28px;
165			height: 8px;
166			-webkit-appearance: none;
167			appearance: none;
168			background: var(--color-bg-panel);
169			border: 1px solid var(--color-border);
170			outline: none;
171			cursor: pointer;
172		}
173	
174		.gate-slider::-webkit-slider-thumb {
175			-webkit-appearance: none;
176			width: 6px;
177			height: 10px;
178			background: var(--color-accent-amber);
179			border: none;
180			cursor: pointer;
181		}
182	</style>

