  1	<script lang="ts">
  2		import { onMount } from 'svelte';
  3		import { midi } from '$lib/stores/midi.svelte';
  4		import { engine } from '$lib/stores/engine.svelte';
  5		import { adapter } from '$lib/adapter';
  6		import type { CalibrationStatus } from '$lib/adapter/types';
  7		import PixelSelect from './PixelSelect.svelte';
  8		import GuitarInputPanel from './GuitarInputPanel.svelte';
  9		import MidiPermissionCard from './MidiPermissionCard.svelte';
 10	
 11		// Virtual input sentinel values — must match
 12		// src-tauri/src/commands/engine.rs.
 13		const VIRTUAL_COMPUTER_KEYBOARD = 999_998;
 14		const VIRTUAL_GUITAR_AUDIO = 999_997;
 15	
 16		type Source = 'midi' | 'keyboard' | 'guitar' | 'voice' | 'none';
 17	
 18		/** Keep hardware MIDI and computer typing distinct. Treating both as
 19		 *  one "MIDI" source made the virtual keyboard look like the only
 20		 *  available device while hardware discovery was still running. */
 21		const sourceFromSelection = (sel: number | null): Source => {
 22			if (sel === null) return 'none';
 23			if (sel === VIRTUAL_GUITAR_AUDIO) return 'guitar';
 24			if (sel === VIRTUAL_COMPUTER_KEYBOARD) return 'keyboard';
 25			return 'midi';
 26		};
 27	
 28		let requestedSource = $state<Source | null>(null);
 29		let source = $derived<Source>(requestedSource ?? sourceFromSelection(midi.selectedInput));
 30	
 31		// Remember the user's last PHYSICAL MIDI device so clicking the MIDI
 32		// radio after a guitar session restores it, instead of either
 33		// auto-selecting Computer Keyboard (hot keyboard mid-take) or
 34		// dropping into Computer-Keyboard as "last MIDI device" (brutal-
 35		// critic #6 — VCK is not a physical MIDI device).
 36		function isPhysicalMidi(sel: number | null): boolean {
 37			return (
 38				sel !== null &&
 39				sel !== VIRTUAL_GUITAR_AUDIO &&
 40				sel !== VIRTUAL_COMPUTER_KEYBOARD
 41			);
 42		}
 43		let lastMidiSelection = $state<number | null>(
 44			isPhysicalMidi(midi.selectedInput) ? midi.selectedInput : null
 45		);
 46		$effect(() => {
 47			if (isPhysicalMidi(midi.selectedInput)) {
 48				lastMidiSelection = midi.selectedInput;
 49			}
 50		});
 51	
 52		// Transient feedback when the user clicks the disabled Voice tile.
 53		// Clears on any other source click.
 54		let voiceUnavailableHint = $state(false);
 55	
 56		async function switchInput(select: () => void) {
 57			const restart = engine.isRunning;
 58			midi.error = null;
 59			try {
 60				if (restart) await engine.stop();
 61				select();
 62				if (restart && midi.selectedInput !== null) {
 63					await engine.start(midi.selectedInput, midi.selectedOutputs);
 64				}
 65			} catch (e) {
 66				midi.error = `Failed to switch input: ${e}`;
 67			}
 68		}
 69	
 70		async function selectSource(next: Source) {
 71			if (next === 'none') return;
 72			if (next === 'voice') {
 73				voiceUnavailableHint = true;
 74				return;
 75			}
 76			requestedSource = next;
 77			voiceUnavailableHint = false;
 78			if (next === 'guitar') {
 79				await switchInput(() => midi.selectVirtualInput(VIRTUAL_GUITAR_AUDIO));
 80				return;
 81			}
 82			if (next === 'keyboard') {
 83				await switchInput(() => midi.selectVirtualInput(VIRTUAL_COMPUTER_KEYBOARD));
 84				return;
 85			}
 86			await midi.refresh();
 87			if (source === 'midi' && isPhysicalMidi(midi.selectedInput)) return;
 88			await switchInput(() => {
 89				const restored =
 90					lastMidiSelection !== null &&
 91					midi.inputs.some((device) => device.index === lastMidiSelection);
 92				const device = restored
 93					? lastMidiSelection
 94					: (midi.inputs[0]?.index ?? null);
 95				if (device === null) midi.clearInput();
 96				else midi.selectInput(device);
 97			});
 98		}
 99	
100		// Calibration profile status (Tauri-only — gated by capability flag).
101		let calibrationStatus = $state<CalibrationStatus | null>(null);
102		let calibrationError = $state<string | null>(null);
103		let calibrationBusy = $state(false);
104	
105		async function refreshCalibrationStatus() {
106			if (!adapter.capabilities.calibrationFlow) return;
107			try {
108				calibrationStatus = await adapter.getCalibrationStatus();
109				calibrationError = null;
110			} catch (e) {
111				calibrationError = `Status check failed: ${e}`;
112			}
113		}
114	
115		async function reloadCalibrationProfile() {
116			// Defense in depth: even though the UI gates the button on the
117			// capability, route through the same check so any future call
118			// site (programmatic, dev console, future surface) can't slip
119			// past the capability contract.
120			if (!adapter.capabilities.calibrationFlow) return;
121			if (calibrationBusy) return;
122			calibrationBusy = true;
123			calibrationError = null;
124			try {
125				calibrationStatus = await adapter.loadCalibrationProfile();
126			} catch (e) {
127				calibrationError = `Reload failed: ${e}`;
128			} finally {
129				calibrationBusy = false;
130			}
131		}
132	
133		async function resetCalibrationToDefault() {
134			if (!adapter.capabilities.calibrationFlow) return;
135			if (calibrationBusy) return;
136			// Inline confirm: a real bad calibration is destructive to undo
137			// (the file is gone). Use a native confirm for now; a follow-up
138			// commit can promote this to an inline toggle-confirm.
139			const ok =
140				typeof window !== 'undefined' &&
141				window.confirm(
142					'Delete the saved calibration profile and reset to defaults? This cannot be undone.'
143				);
144			if (!ok) return;
145			calibrationBusy = true;
146			calibrationError = null;
147			try {
148				calibrationStatus = await adapter.deleteCalibrationProfile();
149			} catch (e) {
150				calibrationError = `Reset failed: ${e}`;
151			} finally {
152				calibrationBusy = false;
153			}
154		}
155	
156		const totalSamples = $derived(
157			calibrationStatus
158				? calibrationStatus.sampleCounts.reduce((a, b) => a + b, 0)
159				: 0
160		);
161	
162		/** Per-string sample distribution display, e.g. "12 8 7 9 6 5".
163		 *  Surfaces under the total so users see whether their calibration
164		 *  sweep covered every string (brutal-critic #5). */
165		const sampleDistribution = $derived(
166			calibrationStatus ? calibrationStatus.sampleCounts.join(' ') : ''
167		);
168	
169		onMount(() => {
170			if (midi.inputs.length === 0 && !midi.isLoading) {
171				midi.refresh();
172			}
173			refreshCalibrationStatus();
174			// Re-check on window focus so a user who drops a profile file in
175			// from another app and tabs back sees the badge flip immediately
176			// (brutal-critic #5).
177			if (typeof window !== 'undefined') {
178				const onFocus = () => refreshCalibrationStatus();
179				window.addEventListener('focus', onFocus);
180				return () => window.removeEventListener('focus', onFocus);
181			}
182		});
183	
184		// Hardware inputs only. Computer Keys has its own top-level source
185		// choice so users never mistake it for the only discovered device.
186		let midiInputOptions = $derived(
187			midi.inputs.map((device) => ({ value: String(device.index), label: device.name }))
188		);
189	
190		async function handleMidiInputChange(value: string) {
191			requestedSource = 'midi';
192			await switchInput(() => {
193				if (value === '') {
194					midi.clearInput();
195					return;
196				}
197				midi.selectInput(parseInt(value, 10));
198			});
199		}
200	
201		function voiceLabel(index: number, count: number): string {
202			const names = ['Soprano', 'Alto', 'Tenor', 'Bass'];
203			if (count <= 4) return `${names[index] || 'Voice'} (${index + 1})`;
204			return `Voice (${index + 1})`;
205		}
206		const voicePositionOptions = $derived(
207			Array.from({ length: engine.voiceCount }, (_, i) => ({
208				value: String(i),
209				label: voiceLabel(i, engine.voiceCount)
210			}))
211		);
212		function onVoicePositionChange(val: string) {
213			engine.setVoicePosition(parseInt(val, 10));
214		}
215	</script>
216	
217	<div class="input-panel">
218		<!-- Source selection separates hardware MIDI from computer typing.
219		     Voice remains reserved for the later vocal pipeline. -->
220		<div class="source-radio pixel-card">
221			<div class="section-header font-ui">SOURCE</div>
222			<div class="radio-row" role="radiogroup" aria-label="Input source">
223				<button
224					class="source-btn pixel-btn font-ui"
225					class:active={source === 'midi'}
226					role="radio"
227					type="button"
228					aria-checked={source === 'midi'}
229					onclick={() => selectSource('midi')}
230					title="Use a connected hardware MIDI controller"
231				>
232					MIDI Controller
233				</button>
234				<button
235					class="source-btn pixel-btn font-ui"
236					class:active={source === 'keyboard'}
237					role="radio"
238					type="button"
239					aria-checked={source === 'keyboard'}
240					onclick={() => selectSource('keyboard')}
241					title="Play notes with the computer keyboard"
242				>
243					Computer Keys
244				</button>
245				<button
246					class="source-btn pixel-btn font-ui"
247					class:active={source === 'guitar'}
248					role="radio"
249					type="button"
250					aria-checked={source === 'guitar'}
251					onclick={() => selectSource('guitar')}
252					title="Live guitar audio in via cpal (pitch-detected)"
253				>
254					Guitar
255				</button>
256				<button
257					class="source-btn pixel-btn font-ui source-disabled"
258					role="radio"
259					type="button"
260					aria-checked="false"
261					aria-disabled="true"
262					onclick={() => selectSource('voice')}
263					title="Voice input (PSOLA harmonizer) lands in v1.4"
264				>
265					Voice
266				</button>
267			</div>
268			{#if voiceUnavailableHint}
269				<p class="voice-hint font-ui">
270					Voice input (PSOLA harmonizer) lands in v1.4 — stay tuned.
271				</p>
272			{/if}
273		</div>
274	
275		<!-- Web MIDI permission card. Browsers gate
276		     navigator.requestMIDIAccess() behind a user gesture. The
277		     component renders nothing on Tauri / Plugin paths and includes
278		     a "DOWNLOAD DESKTOP APP" link for the unsupported-browser
279		     branch (Safari, Firefox without flag) — previously missing
280		     from InputPanel's inline copy. -->
281		<MidiPermissionCard />
282	
283		{#if source === 'midi'}
284			<div class="midi-section pixel-card">
285				<div class="section-header font-ui">MIDI CONTROLLER</div>
286				<div class="input-row">
287					<PixelSelect
288						options={midiInputOptions}
289						value={isPhysicalMidi(midi.selectedInput) ? String(midi.selectedInput) : ''}
290						placeholder={midi.isLoading ? 'Scanning MIDI devices…' : 'Select controller…'}
291						label="MIDI controller"
292						onchange={handleMidiInputChange}
293					/>
294					<button
295						class="refresh-btn pixel-btn"
296						onclick={() => midi.refresh()}
297						disabled={midi.isLoading}
298						title="Refresh MIDI devices"
299					>
300						{midi.isLoading ? '...' : 'R'}
301					</button>
302				</div>
303				{#if !midi.isLoading && midi.inputs.length === 0}
304					<div class="device-status warning font-ui">
305						No hardware MIDI controller found. Connect one, then press R to scan again.
306					</div>
307				{:else if !midi.isLoading}
308					<div class="device-status font-ui">{midi.inputs.length} controller{midi.inputs.length === 1 ? '' : 's'} available</div>
309				{/if}
310	
311				{#if midi.error}
312					<div class="error-text font-ui">{midi.error}</div>
313				{/if}
314	
315				{#if engine.voiceCount > 1}
316					<div class="you-play-row">
317						<span class="you-play-label font-ui">You play</span>
318						<PixelSelect
319							options={voicePositionOptions}
320							value={String(engine.voicePosition)}
321							placeholder="Voice"
322							label="You play"
323							small={true}
324							onchange={onVoicePositionChange}
325						/>
326					</div>
327				{/if}
328			</div>
329		{:else if source === 'keyboard'}
330			<div class="midi-section pixel-card keyboard-source">
331				<div class="section-header font-ui">COMPUTER KEYS</div>
332				<p class="keyboard-copy font-ui">Play immediately from your typing keyboard.</p>
333				<div class="keyboard-hint font-code">Z–M: C3–B3 · Q–U: C4–C5</div>
334				{#if engine.voiceCount > 1}
335					<div class="you-play-row">
336						<span class="you-play-label font-ui">You play</span>
337						<PixelSelect
338							options={voicePositionOptions}
339							value={String(engine.voicePosition)}
340							placeholder="Voice"
341							label="You play"
342							small={true}
343							onchange={onVoicePositionChange}
344						/>
345					</div>
346				{/if}
347			</div>
348		{:else if source === 'guitar'}
349			<GuitarInputPanel />
350	
351			{#if adapter.capabilities.calibrationFlow}
352				<div class="midi-section pixel-card calibration-section">
353					<div class="section-header font-ui">DETECTOR PROFILE</div>
354					{#if calibrationStatus}
355						<div class="calibration-row">
356							<span
357								class="cal-badge font-ui"
358								class:cal-loaded={calibrationStatus.existsOnDisk}
359							>
360								{calibrationStatus.existsOnDisk ? 'Loaded' : 'Default'}
361							</span>
362							<span class="cal-stat font-code">
363								{totalSamples} samples ·
364								v{calibrationStatus.version}
365							</span>
366						</div>
367						<div class="cal-distribution font-code" title="Per-string sample counts (E2 A D G B E4)">
368							strings [{sampleDistribution}]
369						</div>
370						<div class="cal-path font-code" title={calibrationStatus.path}>
371							{calibrationStatus.path || '—'}
372						</div>
373					{/if}
374					{#if calibrationError}
375						<div class="error-text font-ui">{calibrationError}</div>
376					{/if}
377					<div class="cal-actions">
378						<button
379							class="permission-btn pixel-btn font-ui"
380							onclick={reloadCalibrationProfile}
381							disabled={calibrationBusy}
382							title="Re-read guitar_calibration_profile.json from app_data_dir"
383						>
384							{calibrationBusy ? 'LOADING…' : 'RELOAD'}
385						</button>
386						<button
387							class="permission-btn pixel-btn font-ui"
388							onclick={resetCalibrationToDefault}
389							disabled={calibrationBusy || !calibrationStatus?.existsOnDisk}
390							title="Delete the saved profile and reset to defaults"
391						>
392							RESET
393						</button>
394					</div>
395					<p class="cal-note font-ui">
396						Use TUNE GUITAR above to tune the strings. Detector calibration is
397						separate: drop a CLI-generated
398						<code>guitar_calibration_profile.json</code> into the path above,
399						then RELOAD to apply it.
400					</p>
401				</div>
402			{/if}
403		{/if}
404	</div>
405	
406	<style>
407		.input-panel {
408			display: flex;
409			flex-direction: column;
410			gap: 6px;
411			padding: 8px 10px 12px;
412		}
413	
414		.source-radio {
415			padding: 6px 8px;
416		}
417	
418		.section-header {
419			color: var(--color-accent-gold);
420			font-size: var(--font-size-xs);
421			margin-bottom: 6px;
422			letter-spacing: 1.5px;
423			text-transform: uppercase;
424		}
425	
426		.radio-row {
427			display: grid;
428			grid-template-columns: repeat(4, minmax(0, 1fr));
429			gap: 4px;
430		}
431	
432		.source-btn {
433			flex: 1;
434			font-size: var(--font-size-xs) !important;
435			padding: 5px 4px !important;
436			text-align: center;
437			color: var(--color-text-dim);
438			background: var(--color-widget-inactive);
439			border-color: var(--color-border);
440		}
441	
442		.source-btn.active {
443			color: var(--color-accent-cyan);
444			border-color: var(--color-accent-cyan);
445			background: var(--color-bg-panel);
446			box-shadow: 0 0 4px var(--color-accent-cyan);
447		}
448	
449		.source-btn.source-disabled {
450			opacity: 0.4;
451			cursor: not-allowed;
452		}
453	
454		.voice-hint {
455			margin: 4px 0 0;
456			font-size: var(--font-size-xs);
457			color: var(--color-text-secondary);
458			line-height: 1.4;
459		}
