  1	<script lang="ts">
  2		import { onMount } from 'svelte';
  3		import {
  4			engine,
  5			ALL_KEYS,
  6			KEY_DISPLAY,
  7			OCTAVE_MODES,
  8			type HarmonyModeName,
  9			type KeyName,
 10			type OctaveModeName,
 11			type CounterpointSpeciesName
 12		} from '$lib/stores/engine.svelte';
 13		import { adapter } from '$lib/adapter';
 14		import type { PluginInputMode, PluginMidiOutputMode } from '$lib/adapter/types';
 15		import { ui } from '$lib/stores/ui.svelte';
 16		import { midi } from '$lib/stores/midi.svelte';
 17		import { compositeModeOptions, decodeMode, encodeMode } from '$lib/harmony/modeComposite';
 18		import PixelSelect from './PixelSelect.svelte';
 19		import Knob from './Knob.svelte';
 20		import ActiveNotes from './ActiveNotes.svelte';
 21		import Piano from './Piano.svelte';
 22		import Fretboard from './Fretboard.svelte';
 23		import HistoryStrip from './HistoryStrip.svelte';
 24		import LiveLines from './LiveLines.svelte';
 25		import VoiceGenerationChain from './VoiceGenerationChain.svelte';
 26		import CompanionPanel from './CompanionPanel.svelte';
 27		import VoicesPanel from './VoicesPanel.svelte';
 28		import InputPanel from './InputPanel.svelte';
 29		import OutputPanel from './OutputPanel.svelte';
 30		import EnsemblePresetBar from './EnsemblePresetBar.svelte';
 31	
 32		type Visual = 'lines' | 'piano' | 'fretboard' | 'history';
 33		type LineFilter = 'all' | 'player' | 'harmony' | 'canon' | 'counterpoint';
 34	
 35		const pluginSurface = adapter.capabilities.pluginMidiOutputMode;
 36		const keyOptions = ALL_KEYS.map((key) => ({ value: key, label: KEY_DISPLAY[key] }));
 37		// Plugin host currently exposes species 1 only. Do not offer species
 38		// controls that the audio processor cannot apply or automate yet.
 39		const modeOptions = compositeModeOptions().filter(
 40			(option) => !option.value.startsWith('StrictCounterpoint:') || option.value.endsWith('Species1')
 41		);
 42		const voiceOptions = [1, 2, 3, 4].map((count) => ({
 43			value: String(count),
 44			label: count === 1 ? '1 voice' : `${count} voices`
 45		}));
 46		const inputOptions = [
 47			{ value: 'midi', label: 'MIDI' },
 48			{ value: 'audio', label: 'Guitar audio' }
 49		];
 50		const outputOptions = [
 51			{ value: 'full', label: 'Input + Contrapunk' },
 52			{ value: 'pass_through', label: 'Input only' }
 53		];
 54		const octaveOptions = OCTAVE_MODES.map((mode) => ({ value: mode.name, label: mode.label }));
 55	
 56		let inputMode = $state<PluginInputMode>('midi');
 57		let outputMode = $state<PluginMidiOutputMode>('full');
 58		let synthEnabled = $state(true);
 59		let visual = $state<Visual>('lines');
 60		let lineFilter = $state<LineFilter>('all');
 61		let panicSent = $state(false);
 62		let counterpointDetails: HTMLDetailsElement;
 63		let counterpointFocus = $state<'imitative' | 'species'>('imitative');
 64		let counterpointFocusVersion = $state(0);
 65	
 66		let positionOptions = $derived(
 67			Array.from({ length: engine.voiceCount }, (_, index) => ({
 68				value: String(index),
 69				label: index === engine.voicePosition ? `Voice ${index + 1} · you` : `Voice ${index + 1}`
 70			}))
 71		);
 72		let inputActive = $derived(engine.inputNotes.length > 0);
 73		let generatedActive = $derived(
 74			engine.harmonyNotes.length > 0 ||
 75			engine.canonNotes.length > 0 ||
 76			engine.counterpointNotes.length > 0
 77		);
 78		let outputActive = $derived(
 79			outputMode === 'pass_through' ? inputActive : inputActive || generatedActive
 80		);
 81		let harmonyLabel = $derived(
 82			modeOptions.find((option) => option.value === encodeMode(engine.mode, engine.counterpointSpecies))?.label ?? engine.mode
 83		);
 84		let ensembleParts = $derived(
 85			1 +
 86			Math.max(0, engine.voiceCount - 1) +
 87			(engine.companionEnabled && engine.canonEnabled ? Math.max(1, engine.canonVoices.length) : 0) +
 88			(engine.counterpointNotes.length > 0 ? 1 : 0)
 89		);
 90		let timingLabel = $derived(pluginSurface ? 'HOST' : engine.isRunning ? 'LIVE' : 'READY');
 91		let groupFilter = $derived<LineFilter>(engine.canonEnabled ? 'canon' : 'counterpoint');
 92		let companionSummary = $derived(
 93			engine.companionEnabled
 94				? `${engine.canonEnabled ? `Canon ${engine.canonVoices.length || 1}v` : 'Canon off'} · ${engine.counterpointSpecies}`
 95				: 'Off'
 96		);
 97	
 98		async function refreshHostState() {
 99			await engine.syncFromBackend();
100			[inputMode, outputMode, synthEnabled] = await Promise.all([
101				adapter.getPluginInputMode(),
102				adapter.getPluginMidiOutputMode(),
103				adapter.getPluginSynthEnabled()
104			]);
105		}
106	
107		onMount(() => {
108			try {
109				const saved = localStorage.getItem('contrapunk-plugin-visual');
110				if (saved === 'lines' || saved === 'piano' || saved === 'fretboard' || saved === 'history') visual = saved;
111				if (saved === 'ensemble') visual = 'lines';
112			} catch {
113				/* localStorage unavailable */
114			}
115			void refreshHostState();
116			return adapter.onPluginParamsUpdate(() => void refreshHostState());
117		});
118	
119		function setVisual(next: Visual) {
120			visual = next;
121			try {
122				localStorage.setItem('contrapunk-plugin-visual', next);
123			} catch {
124				/* localStorage unavailable */
125			}
126		}
127	
128		function onKeyChange(value: string) {
129			void engine.setAutoKey(false);
130			void engine.setKey(value as KeyName);
131		}
132	
133		function onModeChange(value: string) {
134			const decoded = decodeMode(value);
135			if (decoded.mode) void engine.setMode(decoded.mode as HarmonyModeName);
136			if (decoded.species) {
137				void engine.setCounterpointSpecies(decoded.species as CounterpointSpeciesName);
138			}
139		}
140	
141		function onVoiceCountChange(value: string) {
142			void engine.setVoiceCount(Number(value));
143		}
144	
145		function onPositionChange(value: string) {
146			void engine.setVoicePosition(Number(value));
147		}
148	
149		function onSpread(value: number) {
150			const amount = Math.max(0, Math.min(1, value));
151			void engine.setOctaveMode(amount <= 0.01 ? 'None' : 'Spread');
152			void engine.setOctaveIntensity(amount);
153		}
154	
155		async function onInputMode(value: string) {
156			inputMode = value === 'audio' ? 'audio' : 'midi';
157			await adapter.setPluginInputMode(inputMode);
158		}
159	
160		async function onOutputMode(value: string) {
161			outputMode = value === 'pass_through' ? 'pass_through' : 'full';
162			await adapter.setPluginMidiOutputMode(outputMode);
163		}
164	
165		async function toggleSynth() {
166			synthEnabled = !synthEnabled;
167			await adapter.setPluginSynthEnabled(synthEnabled);
168		}
169	
170		async function toggleRouting() {
171			if (engine.isRunning) {
172				await engine.stop();
173			} else if (midi.selectedInput !== null) {
174				await engine.start(midi.selectedInput, midi.selectedOutputs);
175			}
176		}
177	
178		async function panic() {
179			await adapter.panicAllNotesOff();
180			panicSent = true;
181			window.setTimeout(() => (panicSent = false), 800);
182		}
183	
184		function revealCounterpoint(group: 'imitative' | 'species') {
185			counterpointFocus = group;
186			counterpointFocusVersion += 1;
187			counterpointDetails.open = true;
188			requestAnimationFrame(() => counterpointDetails.scrollIntoView({ behavior: 'smooth', block: 'start' }));
189		}
190	
191		async function addCanonVoice() {
192			if (!engine.companionEnabled) await engine.setCompanionEnabled(true);
193			if (!engine.canonEnabled) await engine.setCanonEnabled(true);
194			if (engine.canonVoices.length < 8) await engine.addCanonVoice();
195			revealCounterpoint('imitative');
196		}
197	
198		async function addSpeciesLine() {
199			if (!engine.companionEnabled) await engine.setCompanionEnabled(true);
200			await adapter.counterpointSetConfig({ enabled: true });
201			revealCounterpoint('species');
202		}
203	</script>
204	
205	<div class="workspace">
206		<header class="signal-bar">
207			<div class="brand-block">
208				<img src="/logo.svg" alt="" class="brand-logo" />
209				<span class="brand font-ui">CONTRAPUNK</span>
210			</div>
211	
212			<div class="signal-path" aria-label="Ensemble signal path">
213				<div class="signal-stage" class:active={inputActive}>
214					<span class="signal-dot input-dot"></span>
215					<span class="font-ui">PLAYER</span>
216				</div>
217				<span class="signal-arrow" aria-hidden="true">›</span>
218				<div class="signal-stage" class:active={generatedActive}>
219					<span class="signal-dot generated-dot"></span>
220					<span class="font-ui">ENSEMBLE</span>
221				</div>
222				<span class="signal-arrow" aria-hidden="true">›</span>
223				<div class="signal-stage" class:active={outputActive}>
224					<span class="signal-dot output-dot"></span>
225					<span class="font-ui">OUTPUT</span>
226				</div>
227			</div>
228	
229			<div class="host-controls">
230				{#if pluginSurface}
231					<div class="mini-select">
232						<span class="mini-label font-ui">SOURCE</span>
233						<PixelSelect options={inputOptions} value={inputMode} label="Source" help="Chooses whether the plugin listens to MIDI notes or detected guitar pitches." small={true} onchange={onInputMode} />
234					</div>
235					<div class="mini-select output-select">
236						<span class="mini-label font-ui">OUTPUT</span>
237						<PixelSelect options={outputOptions} value={outputMode} label="Output" help="Chooses whether output contains the original notes plus Contrapunk, or only the original input." small={true} onchange={onOutputMode} />
238					</div>
239				{:else}
240					<button
241						class="surface-state font-ui"
242						class:active={engine.isRunning}
243						type="button"
244						disabled={!engine.isRunning && midi.selectedInput === null}
245						title="Starts or stops listening to the selected standalone input source."
246						onclick={toggleRouting}
247					>
248						{engine.isRunning ? '■ STOP' : '▶ START'}
249					</button>
