281						value={encodeMode(engine.mode, engine.counterpointSpecies)}
282						label="Harmony mode"
283						help="Chooses the musical rule Contrapunk uses to generate harmonic support from the notes you play."
284						small={true}
285						onchange={onModeChange}
286					/>
287				</div>
288				<div class="control-cell">
289					<div class="control-label"><span>VOICES</span>{#if pluginSurface}<span class="host-badge">HOST</span>{/if}</div>
290					<PixelSelect options={voiceOptions} value={String(engine.voiceCount)} label="Voices" help="Sets the total harmonic texture size, including the part you play." small={true} onchange={onVoiceCountChange} />
291				</div>
292				<div class="control-cell">
293					<div class="control-label"><span>YOU PLAY</span>{#if pluginSurface}<span class="host-badge">HOST</span>{/if}</div>
294					<PixelSelect options={positionOptions} value={String(engine.voicePosition)} label="You play" help="Places your performed note within the texture: upper voice, inner voice, or bass." small={true} onchange={onPositionChange} />
295				</div>
296				<div class="control-cell spread-cell">
297					<Knob
298						value={engine.octaveIntensity}
299						min={0}
300						max={1}
301						step={0.01}
302						defaultValue={0}
303						label="Spread"
304						help="Widens generated harmony across registers. At 0% voices stay close; at 100% each successive harmony voice can move another octave upward."
305						size={42}
306						format={(value) => `${Math.round(value * 100)}%`}
307						onchange={onSpread}
308					/>
309				</div>
310				<div class="control-cell toggle-cell">
311					<div class="control-label"><span>VOICE LEADING</span>{#if pluginSurface}<span class="host-badge">HOST</span>{/if}</div>
312					<button
313						class="toggle-btn font-ui"
314						class:on={engine.voiceLeadingEnabled}
315						type="button"
316						aria-label="Voice leading"
317						aria-pressed={engine.voiceLeadingEnabled}
318						title="Smooths generated parts by preferring nearby notes and reducing awkward jumps between chords."
319						onclick={() => engine.setVoiceLeading(!engine.voiceLeadingEnabled)}
320					>
321						{engine.voiceLeadingEnabled ? 'ON' : 'OFF'}
322					</button>
323				</div>
