325	
326			<section class="performance-panel">
327				<ActiveNotes />
328				<div class="visual-toolbar">
329					<div class="visual-tabs" role="group" aria-label="Visualization">
330						<button class:active={visual === 'lines'} aria-pressed={visual === 'lines'} type="button" title="Shows recent player, harmony, Canon, and Counterpoint notes as moving relationships." onclick={() => setVisual('lines')}>LIVE LINES</button>
331						<button class:active={visual === 'piano'} aria-pressed={visual === 'piano'} type="button" title="Shows currently sounding notes on a playable piano keyboard." onclick={() => setVisual('piano')}>PIANO</button>
332						<button class:active={visual === 'fretboard'} aria-pressed={visual === 'fretboard'} type="button" title="Shows currently sounding notes and scale positions on a guitar fretboard." onclick={() => setVisual('fretboard')}>FRETBOARD</button>
333						<button class:active={visual === 'history'} aria-pressed={visual === 'history'} type="button" title="Shows a compact chronological history of performed and generated notes." onclick={() => setVisual('history')}>HISTORY</button>
334					</div>
335					{#if visual !== 'lines'}
336						<div class="legend font-ui" aria-label="Note color legend">
337							<span><i class="legend-input"></i>Input</span>
338							<span><i class="legend-harmony"></i>Harmony</span>
339							{#if visual === 'piano'}
340								<span><i class="legend-canon"></i>Canon</span>
341								<span><i class="legend-counterpoint"></i>Counterpoint</span>
342							{/if}
343							<span><i class="legend-borrowed"></i>Borrowed</span>
344						</div>
345					{/if}
346				</div>
347				<div class="visual-stage" class:live-lines-stage={visual === 'lines'}>
348					{#if visual === 'lines'}
349						<LiveLines bind:filter={lineFilter} />
350					{:else if visual === 'piano'}
351						<Piano />
352					{:else if visual === 'fretboard'}
353						<Fretboard />
354					{:else}
355						<HistoryStrip />
356					{/if}
357				</div>
358			</section>
359	
360			<section class="relationship-cards" aria-label="How the ensemble responds">
361				<button class="relationship player" class:active={lineFilter === 'player'} type="button" aria-pressed={lineFilter === 'player'} title="Filters Live Lines to only the melody you perform." onclick={() => (lineFilter = 'player')}>
362					<div><strong>YOU</strong><span>{inputActive ? '● PLAYING' : 'SUBJECT'}</span></div>
363					<p>Teal is the live melody you perform. Every generated part listens to it.</p>
364				</button>
365				<button class="relationship harmony" class:active={lineFilter === 'harmony'} type="button" aria-pressed={lineFilter === 'harmony'} title="Filters Live Lines to the chordal voices generated alongside your melody." onclick={() => (lineFilter = 'harmony')}>
366					<div><strong>HARMONIC SUPPORT</strong><span>{Math.max(0, engine.voiceCount - 1)} VOICES</span></div>
367					<p>Magenta voices arrive with you, creating chordal support rather than a separate melody.</p>
368				</button>
369				<button class="relationship counterpoint-group" class:active={lineFilter === groupFilter} type="button" aria-pressed={lineFilter === groupFilter} title="Filters Live Lines to the active imitative or species Counterpoint group." onclick={() => (lineFilter = groupFilter)}>
370					<div><strong>COUNTERPOINT GROUP</strong><span>{engine.canonEnabled ? (engine.imitativeForm === 'strict_canon' ? 'STRICT CANON' : 'FREE IMITATION') : engine.counterpointSpecies}</span></div>
371					<p>Gold imitation follows your subject; lime can move as an independent species line.</p>
372				</button>
373			</section>
374			<div class="relationship-explainer font-ui">
375				<strong>LIVE ENSEMBLE:</strong> compare color, timing, and note shape to see which parts support, imitate, or move independently.
376			</div>
377	
378			<section class="progressive-sections" id="ensemble-groups">
379				<details class="section-card harmonic-section">
380					<summary>
381						<span class="summary-title">HARMONIC SUPPORT</span>
382						<span class="summary-state">{harmonyLabel} · {Math.max(0, engine.voiceCount - 1)} supporting voices</span>
383					</summary>
384					<div class="section-body harmony-details">
385						<div class="detail-control">
386							<span class="detail-label">Octave mode</span>
387							<PixelSelect options={octaveOptions} value={engine.octaveMode} label="Octave mode" help="Chooses how generated harmony is distributed across registers: unchanged, spread, bass/treble split, or mirrored." small={true} onchange={(value) => engine.setOctaveMode(value as OctaveModeName)} />
388						</div>
389						<div class="detail-control">
390							<span class="detail-label">Key detection</span>
391							<button class="toggle-btn font-ui" class:on={engine.autoKey} type="button" aria-label="Automatic key detection" aria-pressed={engine.autoKey} title="When enabled, Contrapunk estimates the key from recent notes. Manual mode uses the selected Key control." onclick={() => engine.setAutoKey(!engine.autoKey)}>
392								{engine.autoKey ? 'AUTO' : 'MANUAL'}
393							</button>
394						</div>
395						<p class="section-copy">
396							{pluginSurface
397								? 'Controls marked HOST are stable DAW parameters for automation and controller assignment.'
398								: 'These controls shape the chordal support that moves with your live melody.'}
399						</p>
400					</div>
401				</details>
402	
403				<details class="section-card arrange-section" open>
404					<summary>
405						<span class="summary-title">ARRANGE YOUR ENSEMBLE</span>
406						<span class="summary-state">{outputMode === 'full' ? 'Input + Contrapunk' : 'Input only'} · Synth {synthEnabled ? 'on' : 'off'}</span>
407					</summary>
408					<div class="section-body arrange-grid">
409						<div class="arrange-main">
410							<VoiceGenerationChain />
411							<div class="arrange-actions">
412								<button class="add-part canon-add font-ui" type="button" title="Adds another delayed imitative voice and opens its group editor." disabled={engine.canonVoices.length >= 8} onclick={addCanonVoice}>+ ADD CANON VOICE</button>
413								<button class="add-part species-add font-ui" type="button" title="Enables the independent species Counterpoint line and opens its group editor." onclick={addSpeciesLine}>+ ADD SPECIES LINE</button>
414							</div>
415							<div class="channel-map font-code">
416								<span>CH1 Melody</span><span>CH2–5 Harmony</span><span>CH6 Canon</span><span>CH7 Counterpoint</span>
417							</div>
418						</div>
419						<aside class="arrange-side">
420							{#if pluginSurface}
421								<div class="setting-row">
422									<span>Built-in synth</span>
423									<button class="toggle-btn font-ui" class:on={synthEnabled} type="button" aria-label="Built-in synth" aria-pressed={synthEnabled} title="Turns Contrapunk's built-in instrument sound on or off. MIDI generation continues either way." onclick={toggleSynth}>{synthEnabled ? 'ON' : 'OFF'}</button>
424								</div>
425							{:else}
426								<p class="section-copy">Choose the built-in synth or external MIDI per voice below.</p>
427							{/if}
428							<p class="section-copy">Routing state stays here; host setup recipes live in the documentation.</p>
429						</aside>
430					</div>

