    84		--color-accent-magenta-dim: #cc2266;   /* Dimmed magenta for subtle uses */
    85		--color-accent-cyan: #33ddff;          /* Secondary accent — electric cyan */
    86		--color-accent-cyan-dim: #2299cc;      /* Dimmed cyan */
    87		--color-accent-teal: #00ccaa;          /* Tertiary — deep teal */
    88		--color-accent-pink: #ff77aa;          /* Soft pink for highlights */
    89		--color-accent-amber: #ffaa33;         /* Warm accent (interchange/borrowed) */
    90		--color-accent-gold: #ffdd44;          /* Bright gold for emphasis */
    91	
    92		/* === Sacred Piano Key Colors (PRESERVED from egui) === */
    93		--color-piano-input: #00e436;       /* Green — input notes (melody) */
    94		--color-piano-harmony: #ff9933;     /* Orange — harmony notes (generated) */
    95		--color-piano-borrowed: #ffaa33;    /* Amber — interchange borrowed notes */
    96		--color-piano-in-scale: #1a1844;    /* Subtle tint for in-scale keys */
    97	
    98		/* === Text === */
    99		--color-text-primary: #e8e0f0;      /* Light lavender — easier on eyes than pure white */
   100		--color-text-secondary: #8888aa;    /* Muted purple-gray */
   101		--color-text-dim: #555577;          /* Very muted — labels, placeholders */
   102	
   103		/* === Borders === */
   104		--color-border: #2a2848;            /* Subtle purple border */
   105		--color-border-active: #ff3388;     /* Magenta glow on active elements */
   106	
   107		/* === Glow Effects (toggled by .reduced-motion) === */
   108		--glow-magenta: 0 0 8px #ff338855, 0 0 20px #ff338822;
   109		--glow-cyan: 0 0 8px #33ddff55, 0 0 20px #33ddff22;
   110		--glow-teal: 0 0 8px #00ccaa55, 0 0 20px #00ccaa22;
   111	
   112		/* === Typography ===
   113		   Native UI typography is clearer at compact DAW sizes and needs no
   114		   runtime font download. JetBrains Mono is reserved for data. */
   115		--font-grotesk: 'Space Grotesk', ui-sans-serif, system-ui, sans-serif;
   116		--font-jetbrains: 'JetBrains Mono', ui-monospace, monospace;
   117		--font-reading: system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
   118	
   119		/* Semantic font roles. */
   120		--font-display: var(--font-reading);
   121		--font-ui: var(--font-reading);
   122		--font-code: var(--font-jetbrains);
   123		--font-mono: var(--font-jetbrains);
   124		--font-body: var(--font-reading);
   125	
   126		/* Base font sizes scale with viewport so the UI stays proportional
   127		   on any monitor. clamp(min, responsive, max) keeps them legible
   128		   everywhere without going microscopic or huge. Multiplied by
   129		   --font-scale for the user-controlled font-size slider (range
   130		   0.75–1.5) — independent of --ui-scale which zooms layout. */
   131		--font-size-xs: calc(clamp(11px, 0.75vmin + 7px, 14px) * var(--font-scale));
   132		--font-size-sm: calc(clamp(13px, 0.9vmin + 7px, 17px) * var(--font-scale));
   133		--font-size-md: calc(clamp(12px, 1.1vmin + 8px, 20px) * var(--font-scale));
   134		--font-size-lg: calc(clamp(16px, 1.5vmin + 10px, 28px) * var(--font-scale));
   135		--font-size-xl: calc(clamp(24px, 2.2vmin + 14px, 40px) * var(--font-scale));
   136	
   137		/* User-controlled scales.
   138		   --ui-scale  → zooms entire layout via html { zoom }. Range 0.75–2.0.
   139		   --font-scale → multiplies font sizes only. Range 0.75–1.5. */
   140		--ui-scale: 1;
   141		--font-scale: 1;
   142	}
   143	
   144	/* === Performance Toggle ===
   145	   Add .reduced-motion to <html> or <body> to disable all glow and animations.
   146	   Intended for lower-powered machines or user preference.
   147	*/
   148	.reduced-motion,
   149	.reduced-motion * {
   150		--glow-magenta: none;
   151		--glow-cyan: none;
   152		--glow-teal: none;
   153		animation: none !important;
   154		transition: none !important;
   155	}
