--- pixel.css
     1	/* =================================================================
     2	   Pixel Art CSS Rules
     3	   Force nearest-neighbor scaling, disable antialiasing,
     4	   sharp corners, and HLD-style neon effects.
     5	   ================================================================= */
     6	
     7	/* === Pixel Art Image Rendering === */
     8	.pixel-art,
     9	[data-pixel] {
    10		image-rendering: pixelated;
    11		image-rendering: -moz-crisp-edges; /* Firefox fallback */
    12		image-rendering: crisp-edges;
    13	}
    14	
    15	/* === Sharp corners everywhere — no border-radius === */
    16	.pixel-card {
    17		border-radius: 0;
    18		background: var(--color-widget-bg);
    19		border: 1px solid var(--color-border);
    20	}
    21	
    22	/* === Pixel Button — base style === */
    23	.pixel-btn {
    24		font-family: var(--font-ui);
    25		font-size: var(--font-size-xs);
    26		padding: 4px 8px;
    27		background: var(--color-widget-inactive);
    28		border: 1px solid var(--color-border);
    29		color: var(--color-text-primary);
    30		cursor: pointer;
    31		transition: none; /* No smooth transitions — pixel art snaps */
    32		border-radius: 0;
    33		outline: none;
    34		-webkit-font-smoothing: none;
    35		text-rendering: optimizeSpeed;
    36	}
    37	
    38	.pixel-btn:hover {
    39		background: var(--color-bg-panel);
    40		border-color: var(--color-accent-cyan-dim);
    41	}
    42	
    43	.pixel-btn.active {
    44		background: var(--color-accent-magenta);
    45		border-color: var(--color-accent-cyan);
    46		box-shadow: var(--glow-magenta);
    47		color: #ffffff;
    48	}
    49	
    50	/* === Neon Glow Pulse (HLD atmosphere) === */
    51	@keyframes glow-pulse {
    52		0%,
    53		100% {
    54			opacity: 0.7;
    55		}
    56		50% {
    57			opacity: 1;
    58		}
    59	}
    60	
    61	.neon-glow {
    62		animation: glow-pulse 3s ease-in-out infinite;
    63	}
    64	
    65	/* === Scan Line Effect (optional atmosphere) === */
    66	@keyframes scan-line {
    67		0% {
    68			transform: translateY(-100%);
    69		}
    70		100% {
    71			transform: translateY(100vh);
    72		}
    73	}
    74	
    75	.scan-line-overlay {
    76		pointer-events: none;
    77		position: fixed;
    78		top: 0;
    79		left: 0;
    80		width: 100%;
    81		height: 2px;
    82		background: linear-gradient(
    83			to bottom,
    84			transparent,
    85			rgba(51, 221, 255, 0.03),
    86			transparent
    87		);
    88		animation: scan-line 8s linear infinite;
    89		z-index: 9999;
    90	}

