  1	/**
  2	 * Guitar Input Store — Reactive Guitar Audio Input State (Svelte 5 Runes)
  3	 *
  4	 * Tracks guitar input configuration (latency, gain, string confidence,
  5	 * technique toggles) and live detection state. Calls the platform adapter
  6	 * to sync device selection and DSP config to the backend.
  7	 */
  8	
  9	import { adapter } from '$lib/adapter';
 10	import { GuitarAudioCapture } from '$lib/audio/guitarCapture';
 11	import { detectPitch, frequencyToMidi, midiToNoteName } from '$lib/audio/pitchDetector';
 12	
 13	const STORAGE_KEY = 'contrapunk-guitar';
 14	
 15	function loadSaved(): Record<string, any> {
 16		try {
 17			const raw = localStorage.getItem(STORAGE_KEY);
 18			return raw ? JSON.parse(raw) : {};
 19		} catch { return {}; }
 20	}
 21	
 22	class GuitarInputStore {
 23		// -- Config (mirrors GuitarInputConfig in Rust) --
 24		latencyMs = $state(21);
 25		gain = $state(1.0);
 26		stringConfidence = $state(0.4);
 27		bendsEnabled = $state(true);
 28		legatoEnabled = $state(true);
 29		slidesEnabled = $state(true);
 30		vibratoEnabled = $state(false);
 31	
 32		// -- Audio device selection --
 33		audioDevices: MediaDeviceInfo[] = $state([]);
 34		selectedDeviceId = $state<string>('');
 35		selectedChannel = $state(1); // 1-indexed for display
 36		maxChannels = $state(2); // depends on selected device
 37	
 38		constructor() {
 39			const saved = loadSaved();
 40			if (saved.latencyMs !== undefined) this.latencyMs = saved.latencyMs;
 41			if (saved.gain !== undefined) this.gain = saved.gain;
 42			if (saved.stringConfidence !== undefined) this.stringConfidence = saved.stringConfidence;
 43			if (saved.bendsEnabled !== undefined) this.bendsEnabled = saved.bendsEnabled;
 44			if (saved.legatoEnabled !== undefined) this.legatoEnabled = saved.legatoEnabled;
 45			if (saved.slidesEnabled !== undefined) this.slidesEnabled = saved.slidesEnabled;
 46			if (saved.vibratoEnabled !== undefined) this.vibratoEnabled = saved.vibratoEnabled;
 47			if (saved.selectedDeviceId) this.selectedDeviceId = saved.selectedDeviceId;
 48			if (saved.selectedChannel) this.selectedChannel = saved.selectedChannel;
 49			if (saved.calibrated) this.calibrated = saved.calibrated;
 50			if (saved.noiseGateEnabled !== undefined) this.noiseGateEnabled = saved.noiseGateEnabled;
 51			if (saved.noiseGateThreshold !== undefined) this.noiseGateThreshold = saved.noiseGateThreshold;
 52			if (saved.freqGateEnabled !== undefined) this.freqGateEnabled = saved.freqGateEnabled;
 53			if (saved.freqGateRange !== undefined) this.freqGateRange = saved.freqGateRange;
 54		}
 55	
 56		private persist() {
 57			try {
 58				localStorage.setItem(STORAGE_KEY, JSON.stringify({
 59					latencyMs: this.latencyMs,
 60					gain: this.gain,
 61					stringConfidence: this.stringConfidence,
 62					bendsEnabled: this.bendsEnabled,
 63					legatoEnabled: this.legatoEnabled,
 64					slidesEnabled: this.slidesEnabled,
 65					vibratoEnabled: this.vibratoEnabled,
 66					selectedDeviceId: this.selectedDeviceId,
 67					selectedChannel: this.selectedChannel,
 68					calibrated: this.calibrated,
 69					noiseGateEnabled: this.noiseGateEnabled,
 70					noiseGateThreshold: this.noiseGateThreshold,
 71					freqGateEnabled: this.freqGateEnabled,
 72					freqGateRange: this.freqGateRange,
 73				}));
 74			} catch {}
 75		}
 76		/** Manual override for channel count (null = auto-detect from device) */
 77		manualMaxChannels = $state<number | null>(null);
 78		audioDeviceError = $state<string>('');
 79	
 80		// -- Live detection state (updated from backend when wired) --
 81		detecting = $state(false);
 82		/** The actual channel being used by the audio capture (1-indexed, for display). */
 83		activeChannel = $state(0);
 84		currentNote = $state('');
 85		currentString = $state('');
 86		currentFret = $state(0);
 87		confidence = $state(0);
 88		velocity = $state(0);
 89		/** Current signal RMS level (0.0-1.0, updated every frame). Non-reactive — only read by canvas. */
 90		signalLevel = 0;
 91		/** Current pitch clarity (0.0-1.0, updated every frame). Non-reactive — only read by canvas. */
 92		signalClarity = 0;
 93	
 94		// -- Gate controls --
 95		/** Noise gate: reject signals below this RMS threshold. */
 96		noiseGateEnabled = $state(true);
 97		noiseGateThreshold = $state(0.01);
 98		/** Frequency gate: reject detections outside expected guitar range (cents from expected). */
 99		freqGateEnabled = $state(true);
100		freqGateRange = $state(1200); // cents — 1 octave
101	
102		// -- Signal history for graphs (rolling buffers) --
103		/** Last N amplitude values for the graph. */
104		amplitudeHistory: number[] = [];
105		/** Last N clarity values for the graph. */
106		clarityHistory: number[] = [];
107		private static readonly HISTORY_SIZE = 128;
108	
109		/** Push a new frame of signal data (called from adapter). */
110		pushSignalFrame(rms: number, clarity: number) {
111			this.signalLevel = Math.min(1, rms * 5);
112			this.signalClarity = clarity;
113			this.amplitudeHistory.push(Math.min(1, rms * 5));
114			this.clarityHistory.push(clarity);
115			if (this.amplitudeHistory.length > GuitarInputStore.HISTORY_SIZE) {
116				this.amplitudeHistory.shift();
117			}
118			if (this.clarityHistory.length > GuitarInputStore.HISTORY_SIZE) {
119				this.clarityHistory.shift();
120			}
121		}
122	
123		// -- Tuning workflow state --
124		calibrated = $state(false);
125		calibrating = $state(false);
126	
127		// -- Tuner state --
128		tunerActive = $state(false);
129		tunerStringIndex = $state(0);
130		tunerDetectedNote = $state('');
131		tunerDetectedFreq = $state(0);
132		tunerCents = $state(0);
133		tunerClarity = $state(0);
134		tunerStatus = $state<'waiting' | 'sharp' | 'flat' | 'in-tune' | 'holding' | 'done'>('waiting');
135		tunerHoldProgress = $state(0); // 0..1
136		tunerPhase = $state<'noise-floor' | 'tuning' | 'complete'>('noise-floor');
137		tunerNoiseProgress = $state(0); // 0..1
138	
139		/** Toggle a technique on/off by name. */
140		toggleTechnique(technique: 'bends' | 'legato' | 'slides' | 'vibrato') {
141			switch (technique) {
142				case 'bends':
143					this.bendsEnabled = !this.bendsEnabled;
144					break;
145				case 'legato':
146					this.legatoEnabled = !this.legatoEnabled;
147					break;
148				case 'slides':
149					this.slidesEnabled = !this.slidesEnabled;
150					break;
151				case 'vibrato':
152					this.vibratoEnabled = !this.vibratoEnabled;
153					break;
154			}
155			this.persist();
445				this.tunerContext = null;
446			}
447			if (this.tunerCapture) {
448				await this.tunerCapture.stop();
449				this.tunerCapture = null;
450			}
451			if (this.tunerAnimFrame !== null) {
452				cancelAnimationFrame(this.tunerAnimFrame);
453				this.tunerAnimFrame = null;
454			}
455		}
456	
457		/** Set latency with bounds checking and sync. */
458		setLatency(value: number) {
459			this.latencyMs = Math.max(1, Math.min(50, value));
460			this.syncConfig(); this.persist();
461		}
462	
463		/** Set gain with bounds checking and sync. */
464		setGain(value: number) {
465			this.gain = Math.max(0.1, Math.min(2.0, Math.round(value * 20) / 20));
466			this.syncConfig(); this.persist();
467		}
468	
469		/** Set string confidence with bounds checking and sync. */
470		setStringConfidence(value: number) {
471			this.stringConfidence = Math.max(0.1, Math.min(1.0, Math.round(value * 20) / 20));
472			this.syncConfig(); this.persist();
473		}
474	
475		/** Enumerate available audio input devices via the Web Audio API. */
476		async enumerateAudioDevices() {
477			if (typeof navigator === 'undefined' || !navigator.mediaDevices) {
478				this.audioDeviceError = 'Audio devices not available on this surface';
479				return;
480			}
481	
482			try {
483				// Request permission first so device labels are populated
484				const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
485				// Stop the stream immediately — we only needed it for permission
486				stream.getTracks().forEach((t) => t.stop());
487	
488				const allDevices = await navigator.mediaDevices.enumerateDevices();
489				this.audioDevices = allDevices.filter((d) => d.kind === 'audioinput');
490				this.audioDeviceError = '';
491	
492				// Auto-select: prefer Audient iD14, otherwise first device
493				if (this.audioDevices.length > 0 && !this.selectedDeviceId) {
494					const audient = this.audioDevices.find((d) =>
495						d.label.toLowerCase().includes('audient')
496					);
497					this.selectDevice(audient ? audient.deviceId : this.audioDevices[0].deviceId);
498				}
499			} catch (err) {
500				// Translate the raw browser/system error into something a
501				// musician can act on. Branch on the standard DOMException
502				// names from the MediaDevices spec; fall back to the raw
503				// message only when we can't classify it. Messages stay
504				// OS-agnostic so Linux/Windows users don't read macOS
505				// instructions.
506				const raw = err instanceof Error ? err : null;
507				const name = raw?.name ?? '';
508				const msg = raw?.message ?? String(err);
509				if (
510					name === 'NotAllowedError' ||
511					name === 'SecurityError' ||
512					/denied permission|not allowed|permission/i.test(msg)
513				) {
514					this.audioDeviceError =
515						"Microphone access denied. Open your system's microphone privacy settings, allow Contrapunk, then re-open the app.";
516				} else if (
