544		/** Select an audio input device and probe its channel count. */
545		selectDevice(deviceId: string) {
546			this.selectedDeviceId = deviceId;
547			this.selectedChannel = 1;
548			this.persist();
549	
550			// Try to determine channel count by opening a stream with the device
551			this.probeChannelCount(deviceId);
552		}
