561		setManualMaxChannels(count: number | null) {
562			this.manualMaxChannels = count;
563			if (count != null && count > 0) {
564				this.maxChannels = count;
565			} else if (this.selectedDeviceId) {
566				// Re-probe to restore auto-detected value
