572		private async probeChannelCount(deviceId: string) {
573			// Skip probing if manual override is set
574			if (this.manualMaxChannels != null && this.manualMaxChannels > 0) {
575				this.maxChannels = this.manualMaxChannels;
576				return;
577			}
578	
579			if (typeof navigator === 'undefined' || !navigator.mediaDevices) return;
580	
581			try {
582				const stream = await navigator.mediaDevices.getUserMedia({
583					audio: {
584						deviceId: { exact: deviceId },
585						// Request all available channels
586						channelCount: { ideal: 32 }
587					}
588				});
589				const track = stream.getAudioTracks()[0];
590				if (track) {
591					const settings = track.getSettings();
592					this.maxChannels = settings.channelCount ?? 2;
593				}
594				stream.getTracks().forEach((t) => t.stop());
595			} catch {
596				// Fallback: assume stereo
597				this.maxChannels = 2;
598			}
599		}
