601		// -- Backend audio devices (from cpal via adapter) --
602		backendAudioDevices: string[] = $state([]);
603	
604		/** Load audio input devices from the backend (cpal). */
605		async loadAudioDevices() {
606			try {
607				this.backendAudioDevices = await adapter.listAudioDevices();
608			} catch {
609				// Backend may not support audio device listing (e.g. WASM)
610				this.backendAudioDevices = [];
611			}
612		}
613	
614		/** Sync the current guitar DSP config to the backend. */
615		async syncConfig() {
616			try {
617				await adapter.setGuitarConfig({
618					latencyMs: this.latencyMs,
619					gain: this.gain,
620					stringConfidence: this.stringConfidence,
621					bends: this.bendsEnabled,
622					legato: this.legatoEnabled,
623					slides: this.slidesEnabled,
624					vibrato: this.vibratoEnabled,
625				});
626			} catch {
627				// Silently ignore — backend may not be ready yet
628			}
629		}
630	
631		/** Sync the selected device and channel to the backend. */
632		async syncDevice() {
633			try {
634				// For Tauri: send the device label (cpal name) instead of browser deviceId hash,
635				// and convert 1-indexed UI channel to 0-indexed for cpal.
636				const device = this.audioDevices.find(d => d.deviceId === this.selectedDeviceId);
